const id = "u-42";
const role = "editor";

const user = {
  id,                          // shorthand: { id: id }
  role,
  ["can_" + role]: true,       // computed key: can_editor
  greet() {
    return `Hi, ${this.id}`;   // method — this set by call site
  },
};

console.log(user.can_editor);  // true
console.log(user.greet());     // Hi, u-42

const token = { value: "abc", meta: { tenant: "t1" } };

// Default: all three flags true for literal keys
console.log(Object.getOwnPropertyDescriptor(token, "value"));
// { value: 'abc', writable: true, enumerable: true, configurable: true }

Object.defineProperty(token, "value", {
  writable: false,   // cannot reassign token.value
  enumerable: false, // hidden from for...in and Object.keys
  configurable: false,
});

token.value = "xyz"; // silent fail in sloppy mode; TypeError in strict
console.log(Object.keys(token)); // ['meta'] — value not listed

const idKey = Symbol("id");
const internal = Symbol("internal");

const cache = {
  [idKey]: "entry-7",
  [internal]: { hits: 0 },
  publicKey: "visible",
};

console.log(cache[idKey]);           // entry-7
console.log(Object.keys(cache));     // ['publicKey'] — symbols omitted
console.log(Object.getOwnPropertySymbols(cache)); // [Symbol(id), Symbol(internal)]

const CONFIG = Object.freeze({ retries: 3, backoff: { ms: 100 } });

function deployWorker(cfg) {
  cfg.backoff.ms = 0; // mutates nested object — freeze is shallow!
  cfg.retries = 10;   // silent no-op (or TypeError in strict)
}

deployWorker(CONFIG);
console.log(CONFIG.backoff.ms); // 0 — shared singleton corrupted
